// MetricKit — real-user signals, no Instruments session needed
import MetricKit

final class MetricSubscriber: NSObject, MXMetricManagerSubscriber {
  override init() {
    super.init()
    MXMetricManager.shared.add(self)
  }
  func didReceive(_ payloads: [MXMetricPayload]) {
    for p in payloads {
      // launch time, hang rate, disk writes, cellular usage
      _ = p.applicationLaunchMetrics
    }
  }
  func didReceive(_ payloads: [MXDiagnosticPayload]) {
    for p in payloads {
      // crash, hang and CPU-exception diagnostics with stacks
      _ = p.hangDiagnostics
    }
  }
}

