import OSLog

let signposter = OSSignposter(subsystem: "com.example.app", category: "launch")

@main
struct MyApp: App {
  init() {
    let state = signposter.beginInterval("App.init")
    defer { signposter.endInterval("App.init", state) }
    // Only what the first frame needs
    Theme.preload()
  }

  var body: some Scene {
    WindowGroup {
      RootView()
        .task {
          // Everything else starts after the first frame is on screen
          await Startup.deferredWork()
        }
    }
  }
}

enum Startup {
  static func deferredWork() async {
    AnalyticsKit.start()
    await FeatureFlags.refresh()
  }
}

